INSERT INTO `repository`
VALUES (10000119, 'wei513723/ring_fifo', 'https://gitee.com/wei513723/ring_fifo.git',
        '# ring_fifo\n\n#### 介绍\n轻巧高效的环形队列。\n\n#### 软件架构\n可选的fifo类型，支持流式数据和帧式数据；单生产者单消费者场景时支持无锁操作。\n\n\n#### 使用说明\n\n1.  简单易用，阅读函数接口注释即可。\n\n#### 参与贡献\n\n1.  Fork 本仓库\n2.  新建 Feat_xxx 分支\n3.  提交代码\n4.  新建 Pull Request\n',
        13600637);
