INSERT INTO `repository`
VALUES (10000348, 'kennana/bbs', 'https://gitee.com/kennana/bbs.git',
        'bbs论坛\n# bbs-php\nphp写的论坛项目 适合新手入门\n# bbs论坛项目\n因为重点放在了PHP编写上，所以前端部分没有特别写~~ 数据提交都是采用FORM表单的形式\n\n#### 项目结构 /bbs/\n\n``` sh\n├── config/ # 项目配置文件\n	├── config.php # 配置文件\n├── core/ # 核心文件\n	├── mysqlDB.php # 数据库连接文件\n	├── upload.php # 上传文件操作\n├── model/ # 业务模块\n	├── list_father.php\n	├── login.php\n	├── publish.php\n	├── publish_deal.php\n	├── register.php\n	├── reply.php\n	├── reply_deal.php\n	├── show.php\n	├── userInfo.php\n	├── validate.php\n├── public/ # 静态资源存放目录\n├── uploads/  # 文件上传目录\n├── views/ # 视图目录\n    ├── index.html   \n    ├── list_father.html\n    ├── list_son.html\n    ├── login.html\n    ├── publish.html\n    ├── quote.html\n    ├── register.html\n    ├── reply.html\n    ├── show.html\n├── index.php # 项目入口文件\n├── init.php # 项目初始化文件',
        5803553);
