INSERT INTO `repository`
VALUES (10000424, 'cnrv-lowRISC/riscv-fesvr', 'https://gitee.com/cnrv-lowRISC/riscv-fesvr.git',
        '==========================================================================\nRISC-V Front-End Server\n==========================================================================\n# Authors : Andrew Waterman, Yunsup Lee\n# Date    : August 28, 2011\n# Version : (under version control)\n\nThe RISC-V Front-End server handles communication between a target\nmachine (which can be a functional simulator, an RTL simulator, or\nan FPGA or ASIC device) and a frontend machine.\n\n--------------------------------------------------------------------------\nBuild Steps\n--------------------------------------------------------------------------\n\n % mkdir build\n % cd build\n % ../configure\n % make\n % [sudo] make install\n\n',
        1975056);
