INSERT INTO `repository`
VALUES (10000501, 'embediot/c_design_pattern', 'https://gitee.com/embediot/c_design_pattern.git',
        '# c_design_pattern\n\n#### 介绍\n嵌入式 C 语言设计模式代码仓库，重构嵌入式 C 语言设计的思维模式\n\n#### 软件架构\n\n源码主要分两部分：\n\n1-嵌入式 C 语言面向对象编程，主要是使用 C 语言实现面向对象的三大特性：封装、继承、多态\n\n2-嵌入式 C 语言设计模式系列，主要是使用 C 语言实现多种设计模式。\n\n#### 源码使用说明\n\n1-源码可以自由传播，复制，使用。\n\n2-源码使用标准C语言编写，某些代码可能依赖标准C库。\n\n3-源码在Linux下使用make构建，其他平台可以自行移植。\n\n',
        25587129);
