INSERT INTO `repository`
VALUES (10000826, 'skyqi/ecstore_prize', 'https://gitee.com/skyqi/ecstore_prize.git',
        '﻿=----------------------------------------=\r\n   ECSTORE 商派电子商务软件\r\n   版本:V2.0   更新:20130801\r\n=----------------------------------------=\r\nECSTORE 是基于新一代电子商务引擎 ECOS 开发的企业级开源网上商店系统，融合 ShopEx 在电子商务领域多年的行业经验，为企业提供快速搭建网店的解决方案，提供安全、稳定的底层架构，采用模块化开发，可无缝对接第三方应用插件，帮助用户轻松拓展网上生意。\r\n\r\n=----------------------------------------=\r\n   ECSTORE 安装环境要求\r\n=----------------------------------------=\r\n1. 服务器环境：Linux、Unix均可，推荐Linux。Windows之作为开发测试环境\r\n2. Web环境：Apache、Ngix、IIS均可，推荐Apache\r\n2. 语言环境：PHP 5.3.0 及以上\r\n3. 数据库：MySQL 3.23 及以上（如果采用MySQL数据库）\r\n4. 其他：Zend Optimizer 2.5.7 及以上\r\n\r\n=----------------------------------------=\r\n   ECSTORE 安装目录结构\r\n=----------------------------------------=\r\napp/ 应用程序目录\r\nconfig/ 配置文件夹\r\ncore/ ecos内核代码\r\nthemes/ 模板文件夹\r\n\r\n=----------------------------------------=\r\n   ECSTORE 服务支持\r\n=----------------------------------------=\r\n如果您在使用过程中遇到技术问题，可通过以下方式获得帮助：\r\nECSTORE 社区：          http://bbs.ec-os.net\r\nECSTORE 官网：          http://www.shopex.cn\r\nECSTORE 商业授权购买：  http://www.shopex.cn\r\n',
        1680298);
